using System;
using System.Collections.Generic;
using NaughtyAttributes;
using Steamworks;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "AchievementData", menuName = "Data/Achievements/Achievement")]
public class AchievementData : ScriptableObject
{
	[SerializeField]
	private string id;

	[SerializeField]
	private string unlockedId;

	[SerializeField]
	private string googlePlayUnlockedId;

	[SerializeField]
	private int ps4ID;

	[SerializeField]
	private int ps5ID;

	[SerializeField]
	private bool enableCustomSaveKey;

	[SerializeField]
	private Sprite achievementSprite;

	[SerializeField]
	private bool enableCustomName;

	[SerializeField]
	private bool useDifferentIDDescriptionOnName;

	[SerializeField]
	private bool enableCustomDescription;

	[SerializeField]
	[ShowIf("enableAchievementDataCustomDescription")]
	private AchievementDataCustomDescription achievementDataCustomDescription;

	[SerializeField]
	private bool enableDifferentIDForDescription;

	[SerializeField]
	[ShowIf("enableDifferentIDForDescription")]
	private string differentIDForDescription;

	[SerializeField]
	private bool enableAchievementVariableAmount;

	[SerializeField]
	[ShowIf("enableAchievementVariableAmount")]
	private int achievementVariableAmount;

	[SerializeField]
	private bool enableSecondAchievementVariableAmount;

	[SerializeField]
	[ShowIf("enableSecondAchievementVariableAmount")]
	private int achievementSecondVariableAmount;

	[SerializeField]
	private bool enableCharacter;

	[SerializeField]
	[ShowIf("enableCharacter")]
	private Character character;

	[SerializeField]
	[ShowIf("enableCharacter")]
	private bool currentCharacterCheck;

	[SerializeField]
	private bool enableAchievementDataHiddenHandler;

	[SerializeField]
	[ShowIf("enableAchievementDataHiddenHandler")]
	private AchievementDataHiddenHandler achievementDataHiddenHandler;

	[SerializeField]
	private bool enableCanBeUnlockedUsingOtherAchievements;

	[SerializeField]
	[ShowIf("enableCanBeUnlockedUsingOtherAchievements")]
	private List<AchievementData> canBeUnlockedUsingOtherAchievementsList;

	[Header("Percentage Progression")]
	[SerializeField]
	private bool dontCountTowardsPercentageProgression;

	[Header("Save System")]
	[SerializeField]
	protected SaveSystem saveSystem;

	[Header("Achievement List")]
	[SerializeField]
	private AchievementsList achievementsList;

	[Header("Demo")]
	[SerializeField]
	private GameController gameController;

	[Header("Arch Oracle Achievement")]
	[SerializeField]
	private bool archOracleAchievement;

	[NonSerialized]
	[ShowNonSerializedField]
	private bool Unlocked;

	[NonSerialized]
	private bool platformAchievementDataCreated;

	[NonSerialized]
	private global::AchievementData platformAchievementData;

	public string ID => id;

	public string XboxAchievementID => unlockedId;

	public string GooglePlayUnlockedId => googlePlayUnlockedId;

	public Sprite AchievementSprite => achievementSprite;

	private bool enableAchievementDataCustomDescription
	{
		get
		{
			if (!enableCustomDescription && !enableCustomName)
			{
				return enableCustomSaveKey;
			}
			return true;
		}
	}

	public int AchievementVariableAmount => achievementVariableAmount;

	public int AchievementSecondVariableAmount => achievementSecondVariableAmount;

	public bool DontCountTowardsPercentageProgression => dontCountTowardsPercentageProgression;

	private global::AchievementData PlatformAchievementData
	{
		get
		{
			if (!platformAchievementDataCreated)
			{
				platformAchievementDataCreated = true;
				platformAchievementData = new global::AchievementData(id, -1L, ps4ID, ps5ID);
			}
			return platformAchievementData;
		}
	}

	public void SetUnlocked(bool value)
	{
		Unlocked = value;
	}

	public bool IsUnlocked()
	{
		if (enableCanBeUnlockedUsingOtherAchievements)
		{
			for (int i = 0; i < canBeUnlockedUsingOtherAchievementsList.Count; i++)
			{
				if (canBeUnlockedUsingOtherAchievementsList[i].IsUnlocked())
				{
					return true;
				}
			}
		}
		return Unlocked;
	}

	public string GetName()
	{
		if (enableCustomName)
		{
			return achievementDataCustomDescription.GetName((useDifferentIDDescriptionOnName ? differentIDForDescription : id) + "_N");
		}
		return GetLocalizedString((useDifferentIDDescriptionOnName ? differentIDForDescription : id) + "_N");
	}

	public string GetDescription()
	{
		string text = "";
		if (enableCharacter)
		{
			text = character.LocalizedCharacterName + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedColon() + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace();
		}
		return text + GetDescriptionWithModifications();
	}

	public bool IsVisibleForPlatform()
	{
		return true;
	}

	private string GetDescriptionWithModifications()
	{
		if (enableCustomDescription)
		{
			if (enableAchievementVariableAmount)
			{
				return achievementDataCustomDescription.GetDescription((enableDifferentIDForDescription ? differentIDForDescription : id) + "_D", achievementVariableAmount);
			}
			return achievementDataCustomDescription.GetDescription((enableDifferentIDForDescription ? differentIDForDescription : id) + "_D");
		}
		if (enableDifferentIDForDescription)
		{
			if (enableSecondAchievementVariableAmount)
			{
				return Smart.Format(GetLocalizedString(differentIDForDescription), achievementVariableAmount, achievementSecondVariableAmount);
			}
			if (enableAchievementVariableAmount)
			{
				return Smart.Format(GetLocalizedString(differentIDForDescription), achievementVariableAmount);
			}
			return GetLocalizedString(differentIDForDescription);
		}
		if (enableSecondAchievementVariableAmount)
		{
			return Smart.Format(GetLocalizedString(id + "_D"), achievementVariableAmount, achievementSecondVariableAmount);
		}
		if (enableAchievementVariableAmount)
		{
			return Smart.Format(GetLocalizedString(id + "_D"), achievementVariableAmount);
		}
		return GetLocalizedString(id + "_D");
	}

	private string GetLocalizedString(string stringID)
	{
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(stringID);
	}

	protected string GetSaveKey()
	{
		if (enableCustomSaveKey)
		{
			return achievementDataCustomDescription.GetSaveKey(id);
		}
		return id;
	}

	public void Unlock(bool saveAndStoreCache = true)
	{
		if (!gameController.IsDemo && !gameController.IsModEnabled && ReferenceSingleton<AssetsReference>.Instance.RunModifiersHandler.ActiveRunModifiers.Count <= 0 && !gameController.IsDailyRun && !saveSystem.HasVirtuesRunCustomizationBattleSaveKey(ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter.CharacterName) && !IsUnlocked() && CharacterCheck() && UnlockCustomRequirementCheck())
		{
			SetUnlocked(value: true);
			saveSystem.SaveAchievementUnlocked(GetSaveKey(), saveAndStoreCache);
			Debug.Log("********* Achievement Unlocked: " + GetName() + " *********");
			achievementsList.CheckArchOracleAchievementUnlock();
			TryUnlockAchievementSteam();
		}
	}

	private void TryUnlockAchievementSteam()
	{
		if (!SteamManager.Initialized)
		{
			Debug.Log("SteamManager not initialized ");
			return;
		}
		Debug.Log("SteamManager Initialized!! ");
		Debug.Log("SteamUserStats.GetAchievement(id, out bool isAchieved): " + SteamUserStats.GetAchievement(id, out var pbAchieved));
		if (SteamUserStats.GetAchievement(id, out pbAchieved))
		{
			Debug.Log("isAchieved: " + pbAchieved);
			if (!pbAchieved)
			{
				Debug.Log("SteamUserStats.SetAchievement(id): " + SteamUserStats.SetAchievement(id));
				SteamUserStats.StoreStats();
			}
		}
	}

	public bool CharacterCheck()
	{
		if (enableCharacter && currentCharacterCheck && ReferenceSingleton<AssetsReference>.Instance.PlayerRunData.CurrentCharacter != character)
		{
			return false;
		}
		return true;
	}

	protected virtual bool UnlockCustomRequirementCheck()
	{
		return true;
	}

	public bool IsHidden()
	{
		if (enableAchievementDataHiddenHandler)
		{
			return achievementDataHiddenHandler.IsHidden();
		}
		return false;
	}

	public void LoadAchievementUnlocked(GameInitializer gameInitializer)
	{
		SetUnlocked(achievementsList.UnlockedAchievements.Contains(GetSaveKey()));
		if (Unlocked && (bool)gameInitializer)
		{
			InvokeAlternatives.InvokeAfterMultipleFrames(gameInitializer, 3, delegate
			{
				TryUnlockAchievementSteam();
			});
		}
	}

	[Button(null)]
	private void LockWithSteamSingleAchievement()
	{
		saveSystem.DeleteAchievementUnlocked(id);
		SetUnlocked(value: false);
		if (!SteamManager.Initialized)
		{
			Debug.Log("SteamManager not initialized ");
		}
		SteamUserStats.ClearAchievement(id);
		SteamUserStats.StoreStats();
	}

	public void LockNoSteamAllAchievements()
	{
	}

	public void UnlockEditorNoSteam()
	{
	}

	[Button(null)]
	public void UnlockEditor()
	{
	}
}
